css:
.voucher-card { border: 2px dashed #64748b; border-radius: 10px; padding: 16px; width: 320px; font-family: -apple-system, Helvetica, Arial, sans-serif; margin-bottom: 12px; }
.voucher-card .brand { font-size: 11px; text-transform: uppercase; letter-spacing: 1px; color: #64748b; }
.voucher-card .site { font-size: 14px; font-weight: 700; margin: 4px 0 10px; }
.voucher-card .code { font-size: 22px; font-weight: 800; letter-spacing: 2px; background: #f1f5f9; border-radius: 6px; padding: 8px 10px; text-align: center; margin-bottom: 10px; }
.voucher-card .meta { font-size: 12px; color: #334155; display: flex; justify-content: space-between; }
.voucher-card .howto { font-size: 11px; color: #64748b; margin-top: 10px; border-top: 1px dashed #cbd5e1; padding-top: 8px; }
